columns.script:
let result = false;

try {
  if(Users['objectGUID'].length > 0) {
  		result = true;
  }

} catch(e) {}

return result;

return {
  // choose a value: 'button' or 'info'
  type: 'info',

  // (optional, struct of the icon, use the cog button to change the properties.)
  icon: {
    name: 'send-backward',
    colorPrimary: 'var(--bs-label)',
    colorPrimaryOpacity: 0.9,
    colorSecondary: 'var(--bs-label)',
    colorSecondaryOpacity: 0.4,
    colorStackPrimary: 'var(--bs-label)',
    colorStackPrimaryOpacity: 0.9,
    colorStackSecondary: 'var(--bs-label)',
    colorStackSecondaryOpacity: 0.1,
    family: 'fadl',
    size: '1x',
  },
  class: '',
  style: {},
  text: ''
}

const result = []

function processItem (name) {
  try {
    const propertyName = name.replace(/ /g, '')
    const value = data.row[propertyName]?.toString()

    if(value === 'true') result.push(name)
  }
  catch(e) {
    console.error('Error processing selection for ', name, e)
  }
}

const names = ['Global','Create','Enable','Disable','Delete','Update','Groups','Name Change','OU Change']

for(const name of names) {
  processItem(name)
}

return {
  type: 'info',
  text: result.join(', ')
}

function toISO8601date(date) {
  if (!date) return undefined

  const asDate = new Date(isNaN(date)? date : Number(date))

  const yyyy = asDate.getFullYear()
  const mm = String(asDate.getMonth() + 1).padStart(2, '0')
  const dd = String(asDate.getDate()).padStart(2, '0')

  return `${yyyy}-${mm}-${dd}`
}

return {
  type: 'info',
  text: toISO8601date(data.row['ExpireDate'])
}

return {
  "type": "button",
  "icon": { name: 'pen' },
  //"class": "btn btn-sm btn-outline-primary opacity-75",
  "class": "btn btn-sm btn-outline-primary",
  "style": {
    "padding": "0.1rem 0.3rem",
    "fontSize": "0.6rem",
    "borderRadius": "6px",
    //"opacity": "0.8"
    "backgroundColor": "rgba(13, 110, 253, 0.1)"
  },
  "text": "Edit"
}

return {
  "type": "button",
  "icon": { name: 'trash-can' },
//  "class": "btn btn-sm btn-outline-danger opacity-75 rounded-pill",
  "class": "btn btn-sm btn-outline-danger",
  "style": {
    "padding": "0.1rem 0.3rem",
    "fontSize": "0.6rem",
    "borderRadius": "6px",
    //"opacity": "0.8"
    "backgroundColor": "rgba(220, 53, 69, 0.1)"
  },
  "text": "Delete"
}

